  function renderVersionLog() {
    const box = document.getElementById('versionLog');
    if (!box) return;
    box.textContent = '';
    const fmt = d => { try { return new Date(d + 'T12:00:00').toLocaleDateString(undefined, { day: 'numeric', month: 'short' }); } catch (_) { return d; } };
    VERSION_LOG.forEach(([v, d, t, sum]) => {
      const row = document.createElement('div');
      row.className = 'set-row';
      row.style.cssText = 'align-items:flex-start;flex-direction:column;gap:2px;padding:8px 0;border-bottom:1px solid var(--border)';
      const head = document.createElement('div');
      head.style.cssText = 'display:flex;justify-content:space-between;width:100%;gap:8px';
      const left = document.createElement('span');
      left.innerHTML = '<b>' + v + '</b>' + (v === CURRENT_VERSION ? ' <span style="color:var(--accent,#1f6fd1)">· this one</span>' : '') + ' — ' + t;
      const right = document.createElement('span');
      right.style.cssText = 'color:var(--text-muted);white-space:nowrap;font-size:var(--text-sm)';
      right.textContent = fmt(d);
      head.append(left, right);
      row.append(head);
      if (sum) { const p = document.createElement('div'); p.style.cssText = 'color:var(--text-muted);font-size:var(--text-sm)'; p.textContent = sum; row.append(p); }
      box.append(row);
    });
  }

  // Keep the header version label in sync with CURRENT_VERSION (was hardcoded before).
  function updateVersionDisplay() {
    const el = document.getElementById('versionDisplay');
    if (el) el.textContent = CURRENT_VERSION;
  }

  // After "Update now": remove ?updated= from the address, and confirm the new
  // version with a short message (also after a plain relaunch into a new version).
  (function afterUpdate() {
    const params = new URLSearchParams(location.search);
    if (params.has('updated')) {
      params.delete('updated');
      const q = params.toString();
      history.replaceState(history.state, '', location.pathname + (q ? '?' + q : '') + location.hash);
    }
    if (sessionStorage.getItem('nb_update_target') === CURRENT_VERSION) sessionStorage.removeItem('nb_update_target');
    let last = null;
    try { last = localStorage.getItem('nb_last_version'); localStorage.setItem('nb_last_version', CURRENT_VERSION); } catch (_) {}
    if (!last || last === CURRENT_VERSION) return;            // first run or same version: nothing to say
    const show = () => {
      const note = document.createElement('div');
      note.setAttribute('role', 'status');
      note.style.cssText = 'position:fixed;top:calc(env(safe-area-inset-top) + 72px);left:50%;transform:translateX(-50%);' +
        'width:max-content;max-width:calc(100% - 40px);background:var(--ink);color:var(--ink-text);padding:10px 18px;' +
        'border-radius:9999px;font-size:var(--text-sm);font-weight:600;box-shadow:var(--shadow-lg);z-index:10002;animation:nbPopIn 300ms ease-out;';
      nbLabel(note, '{i:check} Updated to v ' + CURRENT_VERSION);
      document.body.appendChild(note);
      setTimeout(() => note.remove(), 4500);
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', show); else show();
  })();

  // Check for updates on page load
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => { updateVersionDisplay(); renderVersionLog(); checkForUpdates(); });
  } else {
    updateVersionDisplay();
    renderVersionLog();
    checkForUpdates();
  }

  // Check periodically (every 2 minutes since 0.11.64; a single small file)
  setInterval(checkForUpdates, 2 * 60 * 1000);
  // A home-screen app on iOS is resumed from the background with its timers
  // paused and no reload, so the 5-minute check alone could miss an update
  // for a long time. Check again whenever the app comes back into view.
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') checkForUpdates();
  });
  window.addEventListener('online', checkForUpdates);
